<?php require "config.php";require_admin();header("Content-Type: text/csv; charset=utf-8");header("Content-Disposition: attachment; filename=sfhs-complaints-".date("Y-m-d").".csv");$o=fopen("php://output","w");fputcsv($o,["Tracking Code","Category","Subject","Anonymous","Reporter","Status","Submitted","Updated"]);$r=$conn->query("SELECT tracking_code,category,subject,is_anonymous,reporter_name,status,created_at,updated_at FROM complaints ORDER BY created_at DESC");while($x=$r->fetch_assoc())fputcsv($o,[$x["tracking_code"],$x["category"],$x["subject"],$x["is_anonymous"]?"Yes":"No",$x["is_anonymous"]?"":$x["reporter_name"],$x["status"],$x["created_at"],$x["updated_at"]]);fclose($o);exit;